    int N;
    scanf("%d", &N);
    int v[505];
    for (int i = 0; i < N; i++) {
        scanf("%d", &v[i]);
    }

    int ans = 1; // at least one element can be marked

    // Try every pair of distinct values (a, b) with a < b
    for (int a = 1; a <= N; a++) {
        for (int b = a + 1; b <= N; b++) {
            int dp0 = 0; // max length of alternating subsequence ending with a
            int dp1 = 0; // max length of alternating subsequence ending with b

            for (int i = 0; i < N; i++) {
                int x = v[i];
                if (x == a) {
                    if (dp1 + 1 > dp0) dp0 = dp1 + 1;
                } else if (x == b) {
                    if (dp0 + 1 > dp1) dp1 = dp0 + 1;
                }
            }

            if (dp0 > ans) ans = dp0;
            if (dp1 > ans) ans = dp1;
        }
    }

    printf("%d\n", ans);
    return 0;
}
